package mrpapermoon.whisper.screenimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.material.Dividerimport androidx.compose.material.MaterialThemeimport androidx.compose.material.Scaffoldimport androidx.compose.material.Textimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.tooling.preview.Previewimport androidx.compose.ui.unit.dpimport mrpapermoon.whisper.entity.UserColorimport mrpapermoon.whisper.entity.UserIconimport mrpapermoon.whisper.entity.Whisperimport mrpapermoon.whisper.entity.Whispererimport mrpapermoon.whisper.ui.component.WhisperRowimport mrpapermoon.whisper.ui.theme.WhisperTheme@Composablefun MainScreen(	whispers: List<Whisper>,	onWhisperClick: (Whisper) -> Unit,	modifier: Modifier = Modifier,) {	// TODO: Connect ViewModel / MeshNetworkManager state flow for live whisper feed	// TODO: Add navigation to full whisper view on row click	Scaffold(		modifier = modifier.fillMaxSize(),		// TODO: тонкий статусбар		topBar = {},		// TODO: bottomBar		bottomBar = {},	) { innerPadding ->		if (whispers.isEmpty()) {			Box(				modifier = Modifier					.fillMaxSize()					.padding(innerPadding),				contentAlignment = Alignment.Center,			) {				Text(					text = "No whispers around yet...",					style = MaterialTheme.typography.body1,					color = MaterialTheme.colors.onBackground.copy(alpha = 0.6f),				)			}		} else {			LazyColumn(				modifier = Modifier					.fillMaxSize()					.padding(innerPadding),			) {				items(					items = whispers,					key = { whisper -> whisper.hash },				) { whisper ->					WhisperRow(						whisper = whisper,						onClick = {							// TODO: Handle navigation to WhisperDetailScreen							onWhisperClick(whisper)						},					)					Divider(						color = MaterialTheme.colors.onSurface.copy(alpha = 0.08f),						thickness = 0.5.dp,						startIndent = 72.dp,					)				}			}		}	}}@Preview(showBackground = true)@Composablefun MainScreenPreview() {	val sampleWhispers = listOf(		Whisper(			hash = 1L,			whisperer = Whisperer(id = "1", karma = 10, name = "Alice", color = UserColor.POWDER_BLUSH, icon = UserIcon.EAR),			rumor = "Has anyone seen the green backpack near the coffee shop? Left it around 3 PM."		),		Whisper(			hash = 2L,			whisperer = Whisperer(id = "2", karma = 3, name = "Bob", color = UserColor.BLUE_BELL, icon = UserIcon.VOICE),			rumor = "Mesh connection is super strong today! Testing long range transmission across the courtyard."		),		Whisper(			hash = 3L,			whisperer = Whisperer(id = "3", karma = 0, name = "Charlie", color = UserColor.PERIWINKLE, icon = UserIcon.TOWER),			rumor = "Meeting at 6 PM in room 402."		)	)	WhisperTheme {		MainScreen(			whispers = sampleWhispers,			onWhisperClick = {},		)	}}